        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'mean': 43.333333333333336, 'max': 60, 'label': 'BETA'})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 3, 'mean': 123.33333333333333, 'max': 170, 'label': 'BETA'})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 3, 'mean': 63.333333333333336, 'max': 110, 'label': 'BETA'})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'mean': 0.0, 'max': 0, 'label': 'EMPTY'})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'mean': 203.33333333333334, 'max': 250, 'label': 'BETA'})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'mean': 0.0, 'max': 0, 'label': 'BETA'})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'mean': 150.0, 'max': 240, 'label': 'BETA'})
